import React, { useEffect, useState } from "react";
import Profile from "../../assets/referrals/profile.png";
import OpenInNewIcon from "@mui/icons-material/OpenInNew";
import { useNavigate } from "react-router-dom";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";
import { apisPath, paths } from "../../utils/path";
import http from "../../services/utility";

export default function Referrals() {
  const navigate = useNavigate();
  const [tableHeader, setTableHeader] = useState([
    { name: "Name" },
    { name: "Email" },
    { name: "Phone Number" },
    { name: "Referred by" },
  ]);
  const [tableData, setTableData] = useState([]);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.getReferrals)
      .then(async (res) => {
        // console.log(res?.data?.result);
        setTableData(res?.data?.result);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  return (
    <div className="referrals">
      <h3 className="referrals__heading page_heading">Referrals</h3>
      <div className="referrals__content">
        <table className="referrals__content__table">
          <tr>
            {tableHeader?.map((header, index) => {
              return (
                <th key={index}>
                  <span>
                    {header?.name} <ArrowDropDownIcon />
                  </span>
                </th>
              );
            })}
          </tr>

          {tableData?.map((data, index) => {
            return (
              <tr key={index}>
                <td>
                  <div>
                    <img
                      src={
                        !data?.referTo?.image ? Profile : data?.referTo?.image
                      }
                    />
                    {!data?.referTo?.name || data?.referTo?.name === ""
                      ? "Unknown"
                      : data?.referTo?.name}
                  </div>
                </td>
                <td>
                  {!data?.referTo?.email || data?.referTo?.email === ""
                    ? "Unknown"
                    : data?.referTo?.email}
                </td>
                <td>{data?.referTo?.phone}</td>
                <td>
                  <div>
                    {data?.referBy?.name}
                    <OpenInNewIcon
                      sx={{
                        fontSize: 18,
                        color: "red",
                        cursor: "pointer",
                      }}
                      onClick={() =>
                        navigate(`/${paths?.front?.user?.referrals}/${index}`, {
                          state: { data: data },
                        })
                      }
                    />
                  </div>
                </td>
              </tr>
            );
          })}
        </table>
      </div>
    </div>
  );
}
